import React, { useState, useEffect } from "react";
import { BrowserRouter as Router, Route, Routes, Link, Navigate } from "react-router-dom";
import {
  ResponsiveContainer,
  LineChart,
  XAxis,
  YAxis,
  Tooltip,
  Legend,
  Line,
} from 'recharts';
import "./styles.css";



// Notification Component
const Notification = ({ message, onClose }) => {
  useEffect(() => {
    const timer = setTimeout(() => {
      onClose();
    }, 2000);
    return () => clearTimeout(timer);
  }, [onClose]);

  return (
    <div className="notification">
      {message}
    </div>
  );
};

// Custom OTP Input Component
const OtpInput = ({ value, onChange }) => {
  const handleChange = (index, event) => {
    const newValue = event.target.value;
    if (newValue.length <= 1 && !isNaN(newValue)) {
      const updatedOtp = value.split("");
      updatedOtp[index] = newValue;
      onChange(updatedOtp.join(""));
    }
  };

  return (
    <div className="otp-input">
      {Array.from({ length: 4 }).map((_, index) => (
        <input
          key={index}
          type="text"
          maxLength={1}
          value={value[index] || ""}
          onChange={(e) => handleChange(index, e)}
          className="otp-digit"
        />
      ))}
    </div>
  );
};

// Home Page Component
import Header from './Header'; 
import qrCode from './assets/AIM-Binance.png';
import macosImage from './assets/macos.png'; 
import linuxImage from './assets/linux.png'; 
import windowsImage from './assets/windows.png'; 

// Sample data for charts
const btcData = [
  { time: '10:00', price: 58000 },
  { time: '11:00', price: 48234 },
  { time: '12:00', price: 38100 },
  { time: '13:00', price: 28300 },
  { time: '14:00', price: 58400 },
];

const ethData = [
  { time: '10:00', price: 1800 },
  { time: '11:00', price: 300 },
  { time: '12:00', price: 1820 },
  { time: '13:00', price: 740 },
  { time: '14:00', price: 1850 },
];

const HomePage = () => {
  const [userCount, setUserCount] = useState(265603864);
  const [expandedFaq, setExpandedFaq] = useState(null);

  const toggleFaq = (index) => {
    setExpandedFaq(expandedFaq === index ? null : index);
  };

  useEffect(() => {
    const timer = setTimeout(() => {
      setUserCount(265603975);
    }, 1000);
    return () => clearTimeout(timer);
  }, []);

  const faqs = [
    {
      question: "What is a cryptocurrency exchange?",
      answer: "Cryptocurrency exchanges are digital marketplaces that enable users to buy and sell cryptocurrencies like Bitcoin, Ethereum, and Tether. The Binance exchange is the largest crypto exchange by trade volume."
    },
    {
      question: "What products does Binance provide?",
      answer: "Binance offers spot trading, futures trading, staking, lending, launchpad, savings accounts, and various other crypto financial services."
    },
    {
      question: "How to buy Bitcoin and other cryptocurrencies on Binance",
      answer: "You can buy cryptocurrencies on Binance using credit/debit cards, bank transfers, P2P trading, or by converting other cryptocurrencies."
    },
    {
      question: "How to track cryptocurrency prices",
      answer: "Binance provides real-time price charts with technical indicators, market depth data, and price alerts for all listed cryptocurrencies."
    },
    {
      question: "How to trade cryptocurrencies on Binance",
      answer: "After account verification and depositing funds, use the trading interface to place market, limit, or stop-limit orders with advanced charting tools."
    },
    {
      question: "How to earn from crypto on Binance",
      answer: "Earn through trading, staking, savings products, launchpool, liquidity farming, or referral programs with competitive APYs."
    }
  ];

  return (
    <div className="homePage">
      {/* Header */}
      <Header />

      <h3 className="heading">Smarter Crypto Trading with AIM-Binance!</h3>

      {/* User Count and Trust Us Text */}
      <div className="user-count">
        <span>{userCount.toLocaleString()}</span> USERS
      </div>
      <div className="trust-us">TRUST US</div>

       {/* Getting Started Steps Section */}
       <div className="stepsContainer">
        <h2 className="sectionTitle">Getting Started in 3 Easy Steps</h2>
        <div className="stepsGrid">
          <div className="stepCard">
            <div className="stepImageContainer">
              <img 
                src="/assets/register.png" 
                alt="Register" 
                className="stepImage"
              />
            </div>
            <div className="stepNumber">1</div>
            <h3 className="stepTitle">Register & Verify Account</h3>
            <p className="stepDescription">
              Register your account and complete the individual or entity verification, 
              which is required to comply with local regulation.
            </p>
          </div>
          <div className="stepCard">
            <div className="stepImageContainer">
              <img 
                src="/images/questionnaire-icon.png" 
                alt="Questionnaire" 
                className="stepImage"
              />
            </div>
            <div className="stepNumber">2</div>
            <h3 className="stepTitle">Complete Client Questionnaire</h3>
            <p className="stepDescription">
              Complete the client appropriate questionnaire to ensure Binance's 
              products and services are suitable.
            </p>
          </div>
          <div className="stepCard">
            <div className="stepImageContainer">
              <img 
                src="/images/deposit-icon.png" 
                alt="Deposit" 
                className="stepImage"
              />
            </div>
            <div className="stepNumber">3</div>
            <h3 className="stepTitle">Deposit Funds</h3>
            <p className="stepDescription">
              Add funds to your Binance account via a variety of methods and 
              follow two-factor-authentication to secure your account.
            </p>
          </div>
        </div>
      </div>


      {/* BTC/USDT Chart */}
      <div className="chartContainer">
        <h2 className="chartTitle"> ₿ BTC/USDT Price Trend</h2>
        <ResponsiveContainer width="100%" height={250}>
          <LineChart data={btcData}>
            <XAxis dataKey="time" />
            <YAxis />
            <Tooltip />
            <Legend />
            <Line type="monotone" dataKey="price" stroke="#f7931a" strokeWidth={2} />
          </LineChart>
        </ResponsiveContainer>
      </div>

      {/* ETH/USDT Chart */}
      <div className="chartContainer">
        <h2 className="chartTitle"> ⟠ ETH/USDT Price Trend</h2>
        <ResponsiveContainer width="100%" height={250}>
          <LineChart data={ethData}>
            <XAxis dataKey="time" />
            <YAxis />
            <Tooltip />
            <Legend />
            <Line type="monotone" dataKey="price" stroke="#627eea" strokeWidth={2} />
          </LineChart>
        </ResponsiveContainer>
      </div>

      {/* Market Overview and Trending Coins */}
      <div className="marketContainer">
        <div className="marketOverview">
          <h2 className="sectionTitle"> 💸 Market Overview</h2>
          <div className="marketGrid">
            <div className="marketItem">
              <div className="coinPair">BTC/USDT</div>
              <div className="coinPrice">$56,789.00</div>
              <div className="coinChange positive">+2.5%</div>
            </div>
            <div className="marketItem">
              <div className="coinPair">ETH/USDT</div>
              <div className="coinPrice">$1,789.00</div>
              <div className="coinChange positive">+1.8%</div>
            </div>
            <div className="marketItem">
              <div className="coinPair">BNB/USDT</div>
              <div className="coinPrice">$389.00</div>
              <div className="coinChange negative">-0.3%</div>
            </div>
            <div className="marketItem">
              <div className="coinPair">DOGE/USDT</div>
              <div className="coinPrice">$0.06</div>
              <div className="coinChange positive">+5.2%</div>
            </div>
          </div>
        </div>

        <div className="trendingCoins">
          <h2 className="sectionTitle"> 💰Trending Coins</h2>
          <div className="trendingGrid">
            <div className="trendingItem">
              <div className="coinName">Bitcoin</div>
              <div className="coinChange positive">+2.5%</div>
              <div className="coinSymbol">BTC</div>
            </div>
            <div className="trendingItem">
              <div className="coinName">Ethereum</div>
              <div className="coinChange positive">+1.8%</div>
              <div className="coinSymbol">ETH</div>
            </div>
            <div className="trendingItem">
              <div className="coinName">Binance Coin</div>
              <div className="coinChange negative">-0.3%</div>
              <div className="coinSymbol">BNB</div>
            </div>
            <div className="trendingItem">
              <div className="coinName">Dogecoin</div>
              <div className="coinChange positive">+5.2%</div>
              <div className="coinSymbol">DOGE</div>
            </div>
          </div>
        </div>
      </div>

      {/* Start Earning Today and Sign Up Now */}
      <div className="start-earning-section">
        <h2 className="start-earning-text">Start earning today</h2>
        <Link to="/signup" className="sign-up-button">
          Sign Up Now
        </Link>
      </div>

      <div className="parallelSections">
        {/* Scan to Download App Section */}
        <div className="downloadSection">
          <h2 className="sectionTitle">Scan to Download App</h2>
          <div className="downloadOptions">
            <img 
              src={qrCode} 
              alt="QR Code to Download App"
              className="qrCode"
            />
            <div className="platforms">
              <div className="platformItem">
                <img src={macosImage} alt="MacOS" className="platformIcon" />
                <span>MacOS</span>
              </div>
              <div className="platformItem">
                <img src={windowsImage} alt="Windows" className="platformIcon" />
                <span>Windows</span>
              </div>
              <div className="platformItem">
                <img src={linuxImage} alt="Linux" className="platformIcon" />
                <span>Linux</span>
              </div>
            </div>
          </div>
        </div>

        {/* Account Overview Section */}
        <div className="accountOverview">
          <h2 className="overviewHeading"> $  Average Account Overview</h2>
          <div className="overviewItem">
            <span>Balance</span>
            <span>$12,345.67</span>
          </div>
          <div className="overviewItem">
            <span>Available</span>
            <span>$10,987.65</span>
          </div>
          <div className="overviewItem">
            <span>Unrealized P/L</span>
            <span className="positive">+$1,234.56</span>
          </div>
          <div className="overviewItem">
            <span>Margin Level</span>
            <span>125%</span>
          </div>
          <div className="overviewActions">
            <button className="buyButton">Buy</button>
            <button className="sellButton">Sell</button>
          </div>
        </div>
      </div>

      {/* Statistics Section */}
      <div className="statsContainer">
        <div className="statCard">
          <div className="statHeader">BTC/USDT</div>
          <div className="statName">Bitcoin</div>
          <div className="statValue">58,234.56</div>
          <div className="statChange positive">+2.34%</div>
        </div>
        <div className="statCard">
          <div className="statHeader">ETH/USDT</div>
          <div className="statName">Ethereum</div>
          <div className="statValue">1,834.56</div>
          <div className="statChange negative">-1.23%</div>
        </div>
        <div className="statCard">
          <div className="statHeader">BNB/USDT</div>
          <div className="statName">Binance Coin</div>
          <div className="statValue">334.56</div>
          <div className="statChange positive">+0.87%</div>
        </div>
        <div className="statCard">
          <div className="statHeader">DOGE/USDT</div>
          <div className="statName">Dogecoin</div>
          <div className="statValue">0.0567</div>
          <div className="statChange negative">-2.45%</div>
        </div>
        <div className="statCard">
          <div className="statHeader">LINK/USDT</div>
          <div className="statName">Chainlink</div>
          <div className="statValue">24.56</div>
          <div className="statChange positive">+3.12%</div>
        </div>
        <div className="statCard">
          <div className="statHeader">ADA/USDT</div>
          <div className="statName">Cardano</div>
          <div className="statValue">1.23</div>
          <div className="statChange negative">-0.78%</div>
        </div>
      </div>

            {/* News & Updates Section */}
      <div className="newsContainer">
        <div className="sectionTitle">News & Updates</div>
        <div className="newsGrid">
          <div className="newsItem">
            <h3>Binance Launches New Staking Feature</h3>
            <p>Binance has just released a new staking feature, allowing users to earn passive income on their cryptocurrency holdings.</p>
            <div className="newsTimestamp">2 hours ago</div>
          </div>
          <div className="newsItem">
            <h3>Binance Adds Support for New Trading Pairs</h3>
            <p>Binance has added support for several new trading pairs, including BTC/GBP, ETH/JPY, and BNB/AUD.</p>
            <div className="newsTimestamp">1 day ago</div>
          </div>
          <div className="newsItem">
            <h3>Binance Announces Upcoming Mainnet Upgrade</h3>
            <p>Binance has announced an upcoming mainnet upgrade, which will bring new features and improvements to the platform.</p>
            <div className="newsTimestamp">3 days ago</div>
          </div>
        </div>
      </div>

      {/* FAQ Section */}
      <div className="faqContainer">
        <h2 className="sectionTitle">Frequently Asked Questions</h2>
        
        {faqs.map((faq, index) => (
          <div key={index} className="faqItem">
            <div className="faqQuestion" onClick={() => toggleFaq(index)}>
              <h3>{faq.question}</h3>
              <span className={`caret ${expandedFaq === index ? 'open' : ''}`}>^</span>
            </div>
            {expandedFaq === index && (
              <div className="faqAnswer">
                <p>{faq.answer}</p>
              </div>
            )}
          </div>
        ))}
      </div>



      {/* Footer Section */}
      <footer className="footer">
        <div className="footerSection">
          <h3>Binance</h3>
          <ul>
            <li><Link to="/about">About</Link></li>
            <li><Link to="/careers">Careers</Link></li>
            <li><Link to="/blog">Blog</Link></li>
            <li><Link to="/fees">Fees</Link></li>
          </ul>
        </div>
        <div className="footerSection">
          <h3>Products</h3>
          <ul>
            <li><Link to="/spot">Spot</Link></li>
            <li><Link to="/futures">Futures</Link></li>
            <li><Link to="/earn">Earn</Link></li>
            <li><Link to="/launchpad">Launchpad</Link></li>
          </ul>
        </div>
        <div className="footerSection">
          <h3>Support</h3>
          <ul>
            <li><Link to="/help-center">Help Center</Link></li>
            <li><Link to="/submit-request">Submit a Request</Link></li>
            <li><Link to="/api-docs">API Documentation</Link></li>
            <li><Link to="/status">Status</Link></li>
          </ul>
        </div>
        <div className="footerSection">
          <h3>Legal</h3>
          <ul>
            <li><Link to="/terms">Terms of Use</Link></li>
            <li><Link to="/privacy">Privacy Policy</Link></li>
            <li><Link to="/risk-warnings">Risk Warnings</Link></li>
            <li><Link to="/aml-kyc">AML/KYC</Link></li>
          </ul>
        </div>
        <div className="footerSection">
          <h3>Follow Us</h3>
          <ul className="socialLinks">
            <li><a href="https://twitter.com" target="_blank" rel="noopener noreferrer">Twitter</a></li>
            <li><a href="https://facebook.com" target="_blank" rel="noopener noreferrer">Facebook</a></li>
            <li><a href="https://instagram.com" target="_blank" rel="noopener noreferrer">Instagram</a></li>
            <li><a href="https://telegram.org" target="_blank" rel="noopener noreferrer">Telegram</a></li>
          </ul>
        </div>
      </footer>
    </div>
  );
};

const LoginPage = ({ onLogin }) => {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [otp, setOtp] = useState("");
  const [showOtpField, setShowOtpField] = useState(false);
  const [successMessage, setSuccessMessage] = useState("");

  const handleLogin = () => {
    if (!username || !password) {
      setError("Please fill in all fields.");
      return;
    }

    if (!username.includes('@')) {
      setError("Username must contain an '@' symbol.");
      return;
    }

    // Show OTP field and set success message
    setShowOtpField(true);
    setSuccessMessage("An OTP has been sent to your email.");
  };

  const handleOtpVerification = () => {
    if (otp.length !== 4 || isNaN(otp)) {
      setError("OTP must be a 4-digit number.");
      return;
    }

    setSuccessMessage("OTP Verified! Logging you in...");
    setTimeout(() => {
      onLogin();
      setUsername("");
      setPassword("");
      setOtp("");
      setShowOtpField(false);
    }, 2000);
  };

  // Clear error when username is updated and contains '@'
  useEffect(() => {
    if (username.includes('@')) {
      setError("");
    }
  }, [username]);

  return (
    <div className="loginPage">
      <h2 className="heading">🔒Login</h2>
      <p>Enter your email and password to login to your account.</p>
      {error && <div className="error">{error}</div>}
      {successMessage && <div className="success">{successMessage}</div>}
      <input
        type="text"
        placeholder="Username (must contain @)"
        value={username}
        onChange={(e) => setUsername(e.target.value)}
        className="input"
      />
      <input
        type="password"
        placeholder="Password"
        value={password}
        onChange={(e) => setPassword(e.target.value)}
        className="input"
      />
      {showOtpField && (
        <>
          <p>Enter OTP:</p>
          <OtpInput value={otp} onChange={setOtp} />
        </>
      )}
      <button
        onClick={showOtpField ? handleOtpVerification : handleLogin}
        className="button"
        disabled={showOtpField ? otp.length !== 4 : !username || !password}
      >
        {showOtpField ? "Verify OTP" : "Login"}
      </button>
      <p className="linkText">
        <Link to="/forgot-password" className="link">
          Forgot Password?
        </Link>
      </p>
      <p className="linkText">
        Don't have an account?{" "}
        <Link to="/signup" className="link">
          Sign Up
        </Link>
      </p>
      <div className="footer">
        <p>© 2025 AIM-Binance. All rights reserved.</p>
        <p>
          <a href="#">Terms of Service</a>
          <a href="#">Privacy Policy</a>
          <a href="#">Contact Us</a>
        </p>
      </div>
    </div>
  );
};

// Supporrrt Page Component
const SupportPage = () => {
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    message: ''
  });
  const [errors, setErrors] = useState({});
  const [notification, setNotification] = useState(null);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
    
    // Clear specific error when user types in that field
    if (errors[name]) {
      setErrors(prev => {
        const newErrors = {...prev};
        delete newErrors[name];
        return newErrors;
      });
    }
    
    // Specifically clear email error when '@' is added
    if (name === 'email' && value.includes('@') && errors.email) {
      setErrors(prev => {
        const newErrors = {...prev};
        delete newErrors.email;
        return newErrors;
      });
    }
  };

  const validateForm = () => {
    const newErrors = {};
    if (!formData.name.trim()) newErrors.name = 'Name is required';
    if (!formData.email.trim()) {
      newErrors.email = 'Email is required';
    } else if (!formData.email.includes('@')) {
      newErrors.email = 'Please enter a valid email address';
    }
    if (!formData.message.trim()) newErrors.message = 'Message is required';
    
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    
    if (!validateForm()) return;

    // Simulate API call
    setNotification({
      type: 'success',
      message: 'Your message has been sent successfully!'
    });

    // Clear form
    setFormData({
      name: '',
      email: '',
      message: ''
    });

    // Clear notification after 3 seconds
    setTimeout(() => {
      setNotification(null);
    }, 3000);
  };

  return (
    <div className="loginPage">
      <h2 className="heading">📞Customer Support</h2>
      <p>We're here to help you with any issues or questions you may have.</p>
      
      <div className="supportSections">
        {/* Contact Info Section */}
        <div className="supportContact">
          <h3>Contact Us</h3>
          <p>Email: support@AIM.com</p>
          <p>Phone: +92 79074707</p>
          <p>Live Chat: Available 24/7</p>
        </div>
        
        {/* Support Form Section */}
        <form className="supportForm" onSubmit={handleSubmit}>
          <h3>Send us a message</h3>
          
          {notification && (
            <div className={notification.type === 'success' ? 'success' : 'error'}>
              {notification.message}
            </div>
          )}
          
          <input
            type="text"
            name="name"
            placeholder="Your Name"
            className="input"
            value={formData.name}
            onChange={handleChange}
          />
          {errors.name && <div className="error">{errors.name}</div>}
          
          <input
            type="email"
            name="email"
            placeholder="Your Email"
            className="input"
            value={formData.email}
            onChange={handleChange}
          />
          {errors.email && <div className="error">{errors.email}</div>}
          
          <textarea
            name="message"
            placeholder="Your Message"
            className="input"
            rows="5"
            value={formData.message}
            onChange={handleChange}
          ></textarea>
          {errors.message && <div className="error">{errors.message}</div>}
          
          <button 
            type="submit"
            className="button"
            disabled={!formData.name || !formData.email || !formData.message || errors.email}
          >
            Send Message
          </button>
        </form>
      </div>
      
      <div className="footer">
        <p>© 2025 AIM-Binance. All rights reserved.</p>
        <p>
          <a href="#">Terms of Service</a>
          <a href="#">Privacy Policy</a>
          <a href="#">Contact Us</a>
        </p>
      </div>
    </div>
  );
};
// Forgot Password Page Component
const ForgotPasswordPage = () => {
  const [email, setEmail] = useState("");
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  const [otp, setOtp] = useState("");
  const [showOtpField, setShowOtpField] = useState(false);
  const [isOtpVerified, setIsOtpVerified] = useState(false);
  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");

  const handleSubmit = () => {
    if (!email) {
      setError("Please enter your email, phone, or username.");
      return;
    }

    if (!email.includes('@')) {
      setError("Email must contain an '@' symbol.");
      return;
    }

    setShowOtpField(true);
    setSuccess("A recovery OTP has been sent to your email.");
    setError("");
  };

  const handleOtpVerification = () => {
    if (otp.length !== 4 || isNaN(otp)) {
      setError("OTP must be a 4-digit number.");
      return;
    }

    setIsOtpVerified(true);
    setSuccess("OTP verified. Please enter your new password.");
    setError("");
  };

  const handlePasswordReset = () => {
    if (newPassword !== confirmPassword) {
      setError("Passwords do not match.");
      return;
    }

    setSuccess("Password reset successfully.");
    setError("");
    setEmail("");
    setOtp("");
    setNewPassword("");
    setConfirmPassword("");
    setShowOtpField(false);
    setIsOtpVerified(false);
  };

  return (
    <div className="forgotPasswordPage">
      <h2 className="heading"> 🔓Trouble logging in?</h2>
      <p>Enter your email, phone, or username, and we'll send you an OTP to get back into your account.</p>
      {error && <div className="error">{error}</div>}
      {success && <div className="success">{success}</div>}
      <input
        type="text"
        placeholder="Email, phone, or username"
        value={email}
        onChange={(e) => setEmail(e.target.value)}
        className="input"
      />

      {showOtpField && !isOtpVerified && (
        <>
          <p>Enter OTP:</p>
          <OtpInput value={otp} onChange={setOtp} />
        </>
      )}

      {isOtpVerified && (
        <>
          <input
            type="password"
            placeholder="New Password"
            value={newPassword}
            onChange={(e) => setNewPassword(e.target.value)}
            className="input"
          />
          <input
            type="password"
            placeholder="Confirm New Password"
            value={confirmPassword}
            onChange={(e) => setConfirmPassword(e.target.value)}
            className="input"
          />
        </>
      )}

      <button
        onClick={
          isOtpVerified
            ? handlePasswordReset
            : showOtpField
            ? handleOtpVerification
            : handleSubmit
        }
        className="button"
        disabled={
          isOtpVerified
            ? !newPassword || !confirmPassword
            : showOtpField
            ? !otp
            : !email
        }
      >
        {isOtpVerified
          ? "Reset Password"
          : showOtpField
          ? "Verify OTP"
          : "Send Recovery OTP"}
      </button>

      <p className="linkText">
        <Link to="/login" className="link">
          Back to Login
        </Link>
      </p>

      <div className="footer">
        <p>© 2025 AIM-Binance. All rights reserved.</p>
        <p>
          <a href="#">Terms of Service</a>
          <a href="#">Privacy Policy</a>
          <a href="#">Contact Us</a>
        </p>
      </div>
    </div>
  );
};

const SignupPage = ({ onSignup }) => {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [phone, setPhone] = useState("");
  const [error, setError] = useState("");
  const [otp, setOtp] = useState("");
  const [showOtpField, setShowOtpField] = useState(false);
  const [successMessage, setSuccessMessage] = useState("");

  const handleSignup = () => {
    if (!email || !password || !phone) {
      setError("Please fill in all fields.");
      return;
    }

    if (!email.includes('@')) {
      setError("Email must contain an '@' symbol.");
      return;
    }

    const phoneRegex = /^\+92[\s\-]?\(?(\d{3})\)?[\s\-]?\d{7}$/;
    if (!phoneRegex.test(phone)) {
      setError("Invalid phone number. Please use the format +92XXXXXXXXX, +92 (XXX) XXXXXXX, +92-XXX-XXXXXXX, or +92 XXX XXXXXXX.");
      return;
    }

    // Show OTP field and set success message
    setShowOtpField(true);
    setSuccessMessage("A recovery OTP has been sent to your email.");
  };

  const handleOtpVerification = () => {
    if (otp.length !== 4 || isNaN(otp)) {
      setError("OTP must be a 4-digit number.");
      return;
    }

    setSuccessMessage("OTP Verified! Account created successfully.");
    setTimeout(() => {
      onSignup({ email, password, phone });
      setEmail("");
      setPassword("");
      setPhone("");
      setOtp("");
      setShowOtpField(false);
    }, 2000);
  };

  // Clear error when email or phone is updated and meets the requirements
  useEffect(() => {
    if (email.includes('@')) {
      setError((prevError) =>
        prevError === "Email must contain an '@' symbol." ? "" : prevError
      );
    }

    const phoneRegex = /^\+92[\s\-]?\(?(\d{3})\)?[\s\-]?\d{7}$/;
    if (phoneRegex.test(phone)) {
      setError((prevError) =>
        prevError === "Invalid phone number. Please use the format +92XXXXXXXXX, +92 (XXX) XXXXXXX, +92-XXX-XXXXXXX, or +92 XXX XXXXXXX."
          ? ""
          : prevError
      );
    }
  }, [email, phone]);

  return (
    <div className="signupPage">
      <h2 className="heading">🔐Sign Up</h2>
      <p>Create a new account by filling out the fields below.</p>
      {error && <div className="error">{error}</div>}
      {successMessage && <div className="success">{successMessage}</div>}
      <input
        type="email"
        placeholder="Email (must contain @)"
        value={email}
        onChange={(e) => setEmail(e.target.value)}
        className="input"
      />
      <input
        type="password"
        placeholder="Password (min 8 characters)"
        value={password}
        onChange={(e) => setPassword(e.target.value)}
        className="input"
      />
      <input
        type="text"
        placeholder="Phone Number (+92XXXXXXXXX, +92 (XXX) XXXXXXX, +92-XXX-XXXXXXX, or +92 XXX XXXXXXX)"
        value={phone}
        onChange={(e) => setPhone(e.target.value)}
        className="input"
      />
      {showOtpField && (
        <>
          <p>Enter OTP:</p>
          <OtpInput value={otp} onChange={setOtp} />
        </>
      )}
      <button
        onClick={showOtpField ? handleOtpVerification : handleSignup}
        className="button"
        disabled={showOtpField ? otp.length !== 4 : !email || !password || !phone}
      >
        {showOtpField ? "Verify OTP" : "Sign Up"}
      </button>
      <p className="linkText">
        Already have an account?{" "}
        <Link to="/login" className="link">
          Login
        </Link>
      </p>
      <div className="footer">
        <p>© 2025 AIM-Binance. All rights reserved.</p>
        <p>
          <a href="#">Terms of Service</a>
          <a href="#">Privacy Policy</a>
          <a href="#">Contact Us</a>
        </p>
      </div>
    </div>
  );
};

//KYC Form component
const KYCForm = ({ onKYCSubmit }) => {
  const [name, setName] = useState("");
  const [phoneNumber, setPhoneNumber] = useState("");
  const [documentType, setDocumentType] = useState("passport");
  const [picture, setPicture] = useState(null);
  const [error, setError] = useState("");

  const handleSubmit = () => {
    // Check if any field is empty
    if (!name || !phoneNumber || !documentType || !picture) {
      setError("Must fill every field before submitting.");
      return;
    }

    // Validate phone number format
    const phoneRegex = /^\+92[\s\-]?\(?(\d{3})\)?[\s\-]?\d{7}$/;
    if (!phoneRegex.test(phoneNumber)) {
      setError("Invalid phone number. Please use the format +92XXXXXXXXX, +92 (XXX) XXXXXXX, +92-XXX-XXXXXXX, or +92 XXX XXXXXXX.");
      return;
    }

    // If all validations pass, submit the form
    console.log("Submitting KYC with:", {
      name,
      phoneNumber,
      documentType,
      picture,
    });
    onKYCSubmit();

    // Clear fields after successful submission
    setName("");
    setPhoneNumber("");
    setDocumentType("passport");
    setPicture(null);
    setError(""); // Clear any previous errors
  };

  // Clear error when phone number is updated and meets the requirements
  useEffect(() => {
    const phoneRegex = /^\+92[\s\-]?\(?(\d{3})\)?[\s\-]?\d{7}$/;
    if (phoneRegex.test(phoneNumber)) {
      setError((prevError) =>
        prevError === "Invalid phone number. Please use the format +92XXXXXXXXX, +92 (XXX) XXXXXXX, +92-XXX-XXXXXXX, or +92 XXX XXXXXXX."
          ? ""
          : prevError
      );
    }
  }, [phoneNumber]);

  return (
    <div className="kycPage">
      <h2 className="heading">KYC Verification</h2>
      <p>
        Enter your details, select ID type, upload the document, and submit for
        KYC verification
      </p>
      {error && <div className="error">{error}</div>}
      <input
        type="text"
        placeholder="Full Name"
        value={name}
        onChange={(e) => setName(e.target.value)}
        className="input"
      />
      <input
        type="text"
        placeholder="Phone Number (+92XXXXXXXXX, +92 (XXX) XXXXXXX, +92-XXX-XXXXXXX, or +92 XXX XXXXXXX)"
        value={phoneNumber}
        onChange={(e) => setPhoneNumber(e.target.value)}
        className="input"
      />
      <select
        value={documentType}
        onChange={(e) => setDocumentType(e.target.value)}
        className="input"
      >
        <option value="passport">Passport</option>
        <option value="driver_license">Driver's License</option>
        <option value="ID_card">ID Card</option>
        <option value="picture">Picture</option>
      </select>
      <input
        type="file"
        onChange={(e) => setPicture(e.target.files[0])}
        className="input"
      />
      <button
        onClick={handleSubmit}
        className="button"
        disabled={!name || !phoneNumber || !documentType || !picture}
      >
        Submit
      </button>
      {/* Footer */}
      <div className="footer">
        <p>© 2025 AIM-Binance. All rights reserved.</p>
        <p>
          <a href="#">Terms of Service</a>
          <a href="#">Privacy Policy</a>
          <a href="#">Contact Us</a>
        </p>
      </div>
    </div>
  );
};

